#!/usr/bin/env python3
import os
import sys

def find_broken_symlinks(root_dir):
    """
    Recursively find all broken symbolic links in a directory.
    Returns a sorted list of absolute paths to broken symlinks.
    """
    broken_links = []

    for dirpath, dirnames, filenames in os.walk(root_dir):
        # Get all entries in the current directory (including symlinks)
        try:
            entries = os.listdir(dirpath)
        except (OSError, PermissionError):
            continue

        for entry in entries:
            full_path = os.path.join(dirpath, entry)

            # Check if it's a symbolic link (don't follow the link)
            try:
                if os.path.islink(full_path):
                    # Try to stat the target (this will fail if broken)
                    try:
                        os.stat(full_path)
                        # Symlink is valid
                    except (OSError, FileNotFoundError):
                        # Symlink is broken
                        broken_links.append(full_path)
            except (OSError, PermissionError):
                pass

    return sorted(broken_links)

# Find broken symlinks in /tmp/mcp-workspace/workspace
workspace_dir = "/tmp/mcp-workspace/workspace"
broken_links = find_broken_symlinks(workspace_dir)

# Write results to file
output_file = "/tmp/mcp-workspace/workspace/broken_links.txt"
with open(output_file, 'w') as f:
    for link in broken_links:
        f.write(link + '\n')

print(f"Found {len(broken_links)} broken symbolic links")
if broken_links:
    print("\nBroken links:")
    for link in broken_links:
        print(f"  {link}")
else:
    print("No broken symbolic links found.")

print(f"\nResults written to: {output_file}")

